INSERT INTO cooks (id, name, avatar_url, cover_photo_url, bio, specialty, rating, review_count, arrondissement, neighborhood, lat, lng, pickup_address, verified, is_new) VALUES
('cook-1', 'Amina Benali', 'https://randomuser.me/api/portraits/women/1.jpg', 'https://images.unsplash.com/photo-1664741662725-bd131742b7b7?w=800&h=600&fit=crop&q=80', 'Formée dans un bistrot parisien pendant dix ans avant de se lancer en solo, elle revisite les classiques de grand-mère : blanquette, tarte tatin, quiche.', 'Française', 4.0, 21, 1, 'Les Halles', 48.865654, 2.333881, '2 rue de la Fontaine au Roi, 75001 Paris', 1, 1),
('cook-2', 'Karim Belkacem', 'https://randomuser.me/api/portraits/men/1.jpg', 'https://images.unsplash.com/photo-1785502109199-c5ba5cfe5c9c?w=800&h=600&fit=crop&q=80', 'Ancien second de cuisine dans une brasserie du 6e arrondissement, il a gardé le goût des plats mijotés français appris sur le tas.', 'Française', 4.3, 24, 2, 'Sentier', 48.873791, 2.340481, '9 rue des Poissonniers, 75002 Paris', 0, 0),
('cook-3', 'Ibrahima Diallo', 'https://randomuser.me/api/portraits/men/2.jpg', 'https://images.unsplash.com/photo-1535920527002-b35e96722eb9?w=800&h=600&fit=crop&q=80', 'Arrivé à Paris à 19 ans, il est tombé amoureux de la cuisine bourguignonne en travaillant comme commis — aujourd''hui il la cuisine mieux que personne.', 'Française', 4.1, 10, 3, 'Haut-Marais', 48.858313, 2.360890, '16 rue de la Roquette, 75003 Paris', 0, 0),
('cook-4', 'Mei Chen', 'https://randomuser.me/api/portraits/women/2.jpg', 'https://images.unsplash.com/photo-1608855725042-e95ffd4ca487?w=800&h=600&fit=crop&q=80', 'Diplômée d''une école hôtelière lyonnaise, elle a choisi de se spécialiser dans le répertoire classique français plutôt que dans la cuisine de son enfance.', 'Française', 4.3, 22, 4, 'Le Marais', 48.856427, 2.353598, '23 rue Ramponeau, 75004 Paris', 0, 0),
('cook-5', 'Diego Herrera', 'https://randomuser.me/api/portraits/men/3.jpg', 'https://images.unsplash.com/photo-1769773183948-d24e3c5a2b82?w=800&h=600&fit=crop&q=80', 'Venu d''Argentine pour un stage à Paris, il ne s''est jamais remis du gratin dauphinois de sa colocataire — il en a fait son métier depuis.', 'Française', 4.1, 18, 5, 'Quartier Latin', 48.845061, 2.345119, '30 rue du Faubourg Saint-Denis, 75005 Paris', 1, 0),
('cook-6', 'Thomas Lefebvre', 'https://randomuser.me/api/portraits/men/4.jpg', 'https://images.unsplash.com/photo-1526121831791-40b298302271?w=800&h=600&fit=crop&q=80', 'Un été à Bologne chez la famille de son ex a suffi à le convertir aux pâtes fraîches maison — il n''est jamais reparti côté fourneaux.', 'Italienne', 4.2, 21, 6, 'Saint-Germain-des-Prés', 48.852703, 2.331372, '37 rue Oberkampf, 75006 Paris', 0, 0),
('cook-7', 'Fatou Mbaye', 'https://randomuser.me/api/portraits/women/3.jpg', 'https://images.unsplash.com/photo-1680420574628-225def8eea0a?w=800&h=600&fit=crop&q=80', 'Ancienne commis dans une trattoria du Marais, elle a appris le risotto directement du chef sicilien qui l''a formée.', 'Italienne', 4.3, 21, 7, 'Invalides', 48.859545, 2.321169, '44 rue de la Chapelle, 75007 Paris', 0, 0),
('cook-8', 'Rami Nassar', 'https://randomuser.me/api/portraits/men/5.jpg', 'https://images.unsplash.com/photo-1561841224-9719c8989db2?w=800&h=600&fit=crop&q=80', 'Passionné de cuisine italienne depuis un Erasmus à Rome, il refait chez lui les recettes de sa colocataire romaine.', 'Italienne', 4.0, 28, 8, 'Champs-Élysées', 48.869491, 2.307043, '51 rue de Belleville, 75008 Paris', 0, 1),
('cook-9', 'Samuel Kouassi', 'https://randomuser.me/api/portraits/men/6.jpg', 'https://images.unsplash.com/photo-1571877227200-a0d98ea607e9?w=800&h=600&fit=crop&q=80', 'Autodidacte, il a appris la cuisine italienne en regardant des heures de vidéos de nonnas napolitaines avant de se lancer.', 'Italienne', 4.2, 4, 9, 'Faubourg-Montmartre', 48.877996, 2.336288, '58 rue Myrha, 75009 Paris', 1, 0),
('cook-10', 'Omar Haddad', 'https://randomuser.me/api/portraits/men/7.jpg', 'https://images.unsplash.com/photo-1751200884901-c1c6f43ae1d6?w=800&h=600&fit=crop&q=80', 'Ancien pizzaiolo à Naples pendant trois ans, il a ramené la vraie pâte à longue fermentation dans sa cuisine parisienne.', 'Italienne', 4.5, 35, 10, 'Canal Saint-Martin', 48.870984, 2.356573, '65 rue Sedaine, 75010 Paris', 0, 0),
('cook-11', 'Pierre Durand', 'https://randomuser.me/api/portraits/men/8.jpg', 'https://images.unsplash.com/photo-1571951735163-9557695592ce?w=800&h=600&fit=crop&q=80', 'Parti travailler un an à Tokyo, il en est revenu obsédé par les currys japonais et le riz parfaitement cuit.', 'Asiatique', 4.4, 14, 11, 'Oberkampf', 48.861326, 2.379798, '72 avenue Simon Bolivar, 75011 Paris', 0, 0),
('cook-12', 'Julien Marchand', 'https://randomuser.me/api/portraits/men/9.jpg', 'https://images.unsplash.com/photo-1631709497146-a239ef373cf1?w=800&h=600&fit=crop&q=80', 'Ancien commis dans un restaurant vietnamien du 13e, il y a appris le pho et les nems qu''il refait aujourd''hui chez lui.', 'Asiatique', 4.3, 5, 12, 'Bercy', 48.843346, 2.392098, '79 rue de la Butte-aux-Cailles, 75012 Paris', 0, 0),
('cook-13', 'Baptiste Roy', 'https://randomuser.me/api/portraits/men/10.jpg', 'https://images.unsplash.com/photo-1515022376298-7333f33e704b?w=800&h=600&fit=crop&q=80', 'Sa compagne thaïlandaise lui a transmis les bases du curry vert et du pad thaï — il ne cuisine plus que ça depuis.', 'Asiatique', 4.5, 35, 13, 'Butte-aux-Cailles', 48.831057, 2.359286, '86 rue du Château d''Eau, 75013 Paris', 1, 0),
('cook-14', 'Camila Santos', 'https://randomuser.me/api/portraits/women/4.jpg', 'https://images.unsplash.com/photo-1761315412830-2f59480377b0?w=800&h=600&fit=crop&q=80', 'Fascinée par la cuisine vietnamienne depuis un voyage à Hanoï, elle a appris les bouillons longue cuisson auprès d''une famille locale.', 'Asiatique', 4.4, 33, 14, 'Montparnasse', 48.833099, 2.325678, '93 rue Saint-Maur, 75014 Paris', 0, 0),
('cook-15', 'Salma Bakr', 'https://randomuser.me/api/portraits/women/5.jpg', 'https://images.unsplash.com/photo-1637806930600-37fa8892069d?w=800&h=600&fit=crop&q=80', 'Formée dans un izakaya parisien pendant deux ans, elle maîtrise les currys et bento japonais du quotidien.', 'Asiatique', 4.3, 32, 15, 'Vaugirard', 48.844175, 2.302441, '100 rue de Ménilmontant, 75015 Paris', 0, 1),
('cook-16', 'Antoine Bernard', 'https://randomuser.me/api/portraits/men/11.jpg', 'https://images.unsplash.com/photo-1643381370167-383c9cfd4835?w=800&h=600&fit=crop&q=80', 'Marié à une Sénégalaise, il a appris le thiéboudienne et le mafé directement de sa belle-mère — sa meilleure professeure.', 'Africaine', 4.3, 31, 16, 'Passy', 48.866670, 2.274854, '107 rue Lecourbe, 75016 Paris', 0, 0),
('cook-17', 'Hugo Fontaine', 'https://randomuser.me/api/portraits/men/12.jpg', 'https://images.unsplash.com/photo-1762631383439-18ca3151e825?w=800&h=600&fit=crop&q=80', 'Deux ans de coopération à Dakar lui ont donné le goût du poulet yassa qu''il cuisine depuis son retour.', 'Africaine', 4.0, 25, 17, 'Batignolles', 48.890298, 2.319340, '114 rue de Vaugirard, 75017 Paris', 1, 0),
('cook-18', 'Charlotte Mercier', 'https://randomuser.me/api/portraits/women/6.jpg', 'https://images.unsplash.com/photo-1750677637369-7fae4d9e361b?w=800&h=600&fit=crop&q=80', 'Ancienne collègue d''une cheffe ivoirienne, elle a hérité de ses recettes de garba et d''attiéké.', 'Africaine', 4.2, 24, 18, 'Montmartre', 48.896641, 2.347795, '121 rue Saint-Dominique, 75018 Paris', 0, 0),
('cook-19', 'Valentine Roussel', 'https://randomuser.me/api/portraits/women/7.jpg', 'https://images.unsplash.com/photo-1783408356251-f4953f943bb2?w=800&h=600&fit=crop&q=80', 'Passionnée par la cuisine ghanéenne depuis un stage humanitaire à Accra, elle prépare un jollof rice qui fait référence dans le quartier.', 'Africaine', 4.3, 35, 19, 'Buttes-Chaumont', 48.885022, 2.380442, '128 avenue de Wagram, 75019 Paris', 0, 0),
('cook-20', 'Ravi Kapoor', 'https://randomuser.me/api/portraits/men/13.jpg', 'https://images.unsplash.com/photo-1664993101841-036f189719b6?w=800&h=600&fit=crop&q=80', 'Formé par un chef sénégalais dans un restaurant lyonnais, il perpétue aujourd''hui les recettes ouest-africaines qu''on lui a transmises.', 'Africaine', 4.5, 7, 20, 'Belleville', 48.868897, 2.398448, '5 rue de Passy, 75020 Paris', 0, 0),
('cook-21', 'Marie Lambert', 'https://randomuser.me/api/portraits/women/8.jpg', 'https://images.unsplash.com/photo-1762631934518-f75e233413ca?w=800&h=600&fit=crop&q=80', 'Belle-fille d''une famille algérienne, elle prépare le couscous du vendredi depuis quinze ans — une vraie tradition adoptée.', 'Maghrébine', 4.3, 31, 1, 'Les Halles', 48.862556, 2.333787, '12 rue des Martyrs, 75001 Paris', 1, 0),
('cook-22', 'Sofia Moreau', 'https://randomuser.me/api/portraits/women/9.jpg', 'https://images.unsplash.com/photo-1643019237176-8ae0859f1123?w=800&h=600&fit=crop&q=80', 'Ancienne serveuse dans un restaurant marocain, elle a fini par passer derrière les fourneaux pour apprendre le tajine.', 'Maghrébine', 4.2, 29, 2, 'Sentier', 48.868289, 2.337491, '19 rue Montorgueil, 75002 Paris', 0, 1),
('cook-23', 'Manon Girard', 'https://randomuser.me/api/portraits/women/10.jpg', 'https://images.unsplash.com/photo-1755219302874-10bbd6bf07af?w=800&h=600&fit=crop&q=80', 'Un voyage à Marrakech et un cours de cuisine improvisé chez l''habitant : elle n''a plus jamais arrêté de faire des tajines.', 'Maghrébine', 4.1, 21, 3, 'Haut-Marais', 48.868400, 2.362028, '26 rue des Archives, 75003 Paris', 0, 0),
('cook-24', 'Théo Simon', 'https://randomuser.me/api/portraits/men/14.jpg', 'https://images.unsplash.com/photo-1673283556513-282af10c9882?w=800&h=600&fit=crop&q=80', 'Formé par son ancien colocataire tunisien, il maîtrise la chorba et le brick à l''œuf comme un local.', 'Maghrébine', 4.2, 6, 4, 'Le Marais', 48.849680, 2.358800, '33 rue Mouffetard, 75004 Paris', 0, 0),
('cook-25', 'Giulia Renard', 'https://randomuser.me/api/portraits/women/11.jpg', 'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=800&h=600&fit=crop&q=80', 'Installée à Paris après plusieurs années à Tunis, elle a rapporté dans ses valises les recettes de sa famille d''adoption tunisienne.', 'Maghrébine', 4.1, 26, 5, 'Quartier Latin', 48.840001, 2.350557, '40 rue de la Fontaine au Roi, 75005 Paris', 1, 0),
('cook-26', 'Chloé Petit', 'https://randomuser.me/api/portraits/women/12.jpg', 'https://images.unsplash.com/photo-1697126248475-a537cc5cce28?w=800&h=600&fit=crop&q=80', 'Un stage dans un restaurant libanais du 15e lui a donné le goût du mezze — elle en a fait sa spécialité.', 'Libanaise', 4.1, 15, 6, 'Saint-Germain-des-Prés', 48.854290, 2.331381, '47 rue des Poissonniers, 75006 Paris', 0, 0),
('cook-27', 'Kwame Osei', 'https://randomuser.me/api/portraits/men/15.jpg', 'https://images.unsplash.com/photo-1786174044919-c2119725afa1?w=800&h=600&fit=crop&q=80', 'Ancien collègue de cuisine d''un chef beyrouthin, il a hérité de ses recettes de fattouche et de kebbé.', 'Libanaise', 4.0, 4, 7, 'Invalides', 48.852413, 2.323862, '54 rue de la Roquette, 75007 Paris', 0, 0),
('cook-28', 'Elena Blanchard', 'https://randomuser.me/api/portraits/women/13.jpg', 'https://images.unsplash.com/photo-1561620141-343a829938de?w=800&h=600&fit=crop&q=80', 'Fascinée par la cuisine levantine depuis un voyage à Beyrouth, elle prépare un houmous qui fait sa réputation.', 'Libanaise', 4.3, 9, 8, 'Champs-Élysées', 48.875311, 2.308518, '61 rue Ramponeau, 75008 Paris', 0, 0),
('cook-29', 'Arjun Patel', 'https://randomuser.me/api/portraits/men/16.jpg', 'https://images.unsplash.com/photo-1785031620399-c56a45c4af63?w=800&h=600&fit=crop&q=80', 'Formé auprès d''une famille libanaise du quartier, il maîtrise le taboulé et le chawarma maison.', 'Libanaise', 4.3, 16, 9, 'Faubourg-Montmartre', 48.881961, 2.339175, '68 rue du Faubourg Saint-Denis, 75009 Paris', 1, 1),
('cook-30', 'Moussa Traoré', 'https://randomuser.me/api/portraits/men/17.jpg', 'https://images.unsplash.com/photo-1596288747490-51ed1661a86f?w=800&h=600&fit=crop&q=80', 'Ancien cuisinier dans une épicerie fine libanaise, il a appris sur le tas les mezze qu''il propose aujourd''hui.', 'Libanaise', 4.3, 17, 10, 'Canal Saint-Martin', 48.870263, 2.365097, '75 rue Oberkampf, 75010 Paris', 0, 0),
('cook-31', 'Camille Rousseau', 'https://randomuser.me/api/portraits/women/14.jpg', 'https://images.unsplash.com/photo-1742599361498-79824d24e355?w=800&h=600&fit=crop&q=80', 'Six mois de voyage en Inde du Nord lui ont donné envie d''apprendre le curry auprès de familles locales — elle ne s''est plus arrêtée.', 'Indienne', 4.3, 26, 11, 'Oberkampf', 48.862960, 2.383242, '82 rue de la Chapelle, 75011 Paris', 0, 0),
('cook-32', 'Linh Tran', 'https://randomuser.me/api/portraits/women/15.jpg', 'https://images.unsplash.com/photo-1626500154744-e4b394ffea16?w=800&h=600&fit=crop&q=80', 'Ancienne commis dans un restaurant indien du 18e, elle a appris le biryani et le dahl directement du chef.', 'Indienne', 4.2, 28, 12, 'Bercy', 48.835573, 2.389743, '89 rue de Belleville, 75012 Paris', 0, 0),
('cook-33', 'Nicolas Bertrand', 'https://randomuser.me/api/portraits/men/18.jpg', 'https://images.unsplash.com/photo-1596797038530-2c107229654b?w=800&h=600&fit=crop&q=80', 'Formé par son mentor, un chef originaire du Kerala, il prépare un curry d''agneau qui ne triche pas sur les épices.', 'Indienne', 4.0, 35, 13, 'Butte-aux-Cailles', 48.829302, 2.354905, '96 rue Myrha, 75013 Paris', 1, 0),
('cook-34', 'Maxime Chevalier', 'https://randomuser.me/api/portraits/men/19.jpg', 'https://images.unsplash.com/photo-1668236543090-82eba5ee5976?w=800&h=600&fit=crop&q=80', 'Passionné de cuisine indienne depuis un stage en cuisine à Bombay, il refait chez lui les currys appris là-bas.', 'Indienne', 4.3, 15, 14, 'Montparnasse', 48.830443, 2.330423, '103 rue Sedaine, 75014 Paris', 0, 0),
('cook-35', 'Farid Amrani', 'https://randomuser.me/api/portraits/men/20.jpg', 'https://images.unsplash.com/photo-1559528896-c5310744cce8?w=800&h=600&fit=crop&q=80', 'Sa colocataire indienne lui a transmis les bases du dahl et du naan — dix ans plus tard, c''est devenu son métier.', 'Indienne', 4.4, 21, 15, 'Vaugirard', 48.837966, 2.299357, '110 avenue Simon Bolivar, 75015 Paris', 0, 0),
('cook-36', 'Youssef Amrani', 'https://randomuser.me/api/portraits/men/21.jpg', 'https://images.unsplash.com/photo-1512685076844-4161e436c4f5?w=800&h=600&fit=crop&q=80', 'Un an passé à Lima l''a converti au ceviche — il importe même ses piments depuis son fournisseur péruvien.', 'Sud-Américaine', 4.2, 7, 16, 'Passy', 48.865653, 2.278977, '117 rue de la Butte-aux-Cailles, 75016 Paris', 0, 1),
('cook-37', 'Lucas Girard', 'https://randomuser.me/api/portraits/men/22.jpg', 'https://images.unsplash.com/photo-1535399831218-d5bd36d1a6b3?w=800&h=600&fit=crop&q=80', 'Ancien élève d''un chef argentin à Buenos Aires, il maîtrise l''asado et le chimichurri comme personne.', 'Sud-Américaine', 4.3, 15, 17, 'Batignolles', 48.887440, 2.318770, '124 rue du Château d''Eau, 75017 Paris', 1, 0),
('cook-38', 'Priya Sharma', 'https://randomuser.me/api/portraits/women/16.jpg', 'https://images.unsplash.com/photo-1606791496080-69a6e309f42c?w=800&h=600&fit=crop&q=80', 'Fascinée par la cuisine péruvienne depuis un voyage à Lima, elle prépare un ceviche qui fait référence dans le quartier.', 'Sud-Américaine', 4.1, 7, 18, 'Montmartre', 48.893439, 2.349780, '131 rue Saint-Maur, 75018 Paris', 0, 0),
('cook-39', 'Yasmine Cherif', 'https://randomuser.me/api/portraits/women/17.jpg', 'https://images.unsplash.com/photo-1619683909099-03814b162136?w=800&h=600&fit=crop&q=80', 'Formée par une famille colombienne du quartier, elle a appris les arepas et les empanadas maison.', 'Sud-Américaine', 4.0, 10, 19, 'Buttes-Chaumont', 48.882896, 2.380934, '8 rue de Ménilmontant, 75019 Paris', 0, 0),
('cook-40', 'Hana Kobayashi', 'https://randomuser.me/api/portraits/women/18.jpg', 'https://images.unsplash.com/photo-1788601988443-9b859ba3fdf4?w=800&h=600&fit=crop&q=80', 'Deux ans à Rio lui ont donné le goût de la feijoada qu''elle cuisine depuis son retour à Paris.', 'Sud-Américaine', 4.3, 22, 20, 'Belleville', 48.865839, 2.403479, '15 rue Lecourbe, 75020 Paris', 0, 0),
('cook-41', 'Nadia Haddad', 'https://randomuser.me/api/portraits/women/19.jpg', 'https://images.unsplash.com/photo-1542354254-d856f94968ea?w=800&h=600&fit=crop&q=80', 'Passée au 100% végétal après un documentaire qui l''a marquée, elle réinvente les classiques réconfortants sans viande.', 'Végétarienne', 4.3, 15, 1, 'Les Halles', 48.856964, 2.337194, '22 rue de Vaugirard, 75001 Paris', 1, 0),
('cook-42', 'Léa Dubois', 'https://randomuser.me/api/portraits/women/20.jpg', 'https://images.unsplash.com/photo-1552422273-f56265a5f375?w=800&h=600&fit=crop&q=80', 'Ancienne cheffe de cuisine traditionnelle, elle s''est reconvertie au végétarien par conviction il y a cinq ans.', 'Végétarienne', 4.1, 25, 2, 'Sentier', 48.872693, 2.343997, '29 rue Saint-Dominique, 75002 Paris', 0, 0),
('cook-43', 'Aïcha Ndiaye', 'https://randomuser.me/api/portraits/women/21.jpg', 'https://images.unsplash.com/photo-1778439800378-6f67fd8ec219?w=800&h=600&fit=crop&q=80', 'Diététicienne de formation, elle a développé des recettes végétariennes équilibrées et gourmandes pour ses voisins.', 'Végétarienne', 4.3, 10, 3, 'Haut-Marais', 48.857708, 2.365720, '36 avenue de Wagram, 75003 Paris', 0, 1),
